// Extract contacts array into individual items
const response = $input.first().json;
const contacts = response.contacts || [];

if (contacts.length === 0) {
  return [{ json: { error: 'No contacts found', total: 0 } }];
}

return contacts.map(c => ({ json: c }));

// Get contact data from the loop (before HTTP replaced it)
const contact = $('Loop Contacts').first().json;
const searchResult = $input.first().json;
const conversations = searchResult.conversations || [];

// Find WhatsApp conversation
const whatsappConv = conversations.find(c => {
  const cType = (c.type || '').toLowerCase();
  const lastType = (c.lastMessageType || '').toLowerCase();
  return cType.includes('whatsapp') ||
    cType === 'type_phone' ||
    lastType.includes('whatsapp') ||
    cType === 'custom_whatsapp';
});

if (!whatsappConv) {
  return [{
    json: {
      skip: true,
      contactId: contact.id,
      contactName: contact.firstName || contact.name || 'Unknown',
      reason: 'no_whatsapp_conversation'
    }
  }];
}

return [{
  json: {
    skip: false,
    conversationId: whatsappConv.id,
    contactId: contact.id,
    firstName: contact.firstName || '',
    lastName: contact.lastName || '',
    tags: contact.tags || [],
    email: contact.email || '',
    phone: contact.phone || '',
    lastMessageDate: whatsappConv.lastMessageDate || null
  }
}];

// Contact context from Process Search Results
const ctx = $('Process Search Results').first().json;

// Messages from Get Messages HTTP response
// GHL nests as { messages: { messages: [...], lastMessageId, nextPage } }
const messagesData = $input.first().json;
const rawMessages = messagesData.messages || {};
const messages = Array.isArray(rawMessages) ? rawMessages : (rawMessages.messages || []);

// Sort messages by date (oldest first)
const sortedMessages = messages.sort((a, b) =>
  new Date(a.dateAdded || a.createdAt || 0) - new Date(b.dateAdded || b.createdAt || 0)
);

// === 24h WINDOW CHECK ===
const now = Date.now();
const lastInbound = [...sortedMessages].reverse().find(m =>
  m.direction === 'inbound' || m.direction === 1 || m.type === 'TYPE_INBOUND'
);
const canSendFreeForm = !!(lastInbound &&
  (now - new Date(lastInbound.dateAdded || lastInbound.createdAt).getTime()) < 24 * 60 * 60 * 1000);

// === TAG ANALYSIS ===
const tags = (ctx.tags || []).map(t => t.toLowerCase());
const hasConnectTag = tags.includes('connect');

// === WEBINAR CONFIG ===
// UPDATE THESE when new webinars are scheduled
// Format: { name: "Display Name", date: "YYYY-MM-DD", tag: "tag-name" }
const upcomingWebinars = [
  // { name: "March Masterclass", date: "2026-03-28", tag: "webinar-march-2026" }
];

const threeWeeksMs = 21 * 24 * 60 * 60 * 1000;
const relevantWebinars = upcomingWebinars.filter(w => {
  const wDate = new Date(w.date).getTime();
  return wDate > now && wDate < (now + threeWeeksMs);
});

const webinarStatus = relevantWebinars.map(w => ({
  ...w,
  isRegistered: tags.includes(w.tag.toLowerCase()),
  hasAttended: tags.some(t => t.includes(w.tag.toLowerCase() + '-attended'))
}));

// Past webinars (for post-workshop follow-up)
const pastWebinars = upcomingWebinars.filter(w => {
  const wDate = new Date(w.date).getTime();
  return wDate < now && wDate > (now - 14 * 24 * 60 * 60 * 1000);
}).map(w => ({
  ...w,
  isRegistered: tags.includes(w.tag.toLowerCase()),
  hasAttended: tags.some(t => t.includes(w.tag.toLowerCase() + '-attended')),
  daysAttended: tags.filter(t => t.startsWith(w.tag.toLowerCase() + '-day')).map(t => t.replace(w.tag.toLowerCase() + '-day', ''))
}));

// === CONVERSATION HISTORY ===
const history = sortedMessages.map(m => {
  const isInbound = m.direction === 'inbound' || m.direction === 1 || m.type === 'TYPE_INBOUND';
  const sender = isInbound ? ctx.firstName : 'Shimrit';
  const body = m.body || m.message || m.text || '[media/attachment]';
  const date = m.dateAdded || m.createdAt || '';
  return `[${date}] ${sender}: ${body}`;
}).join('\n');

// Last message info
const lastMessage = sortedMessages[sortedMessages.length - 1];
const lastMessageIsInbound = !!(lastMessage &&
  (lastMessage.direction === 'inbound' || lastMessage.direction === 1 || lastMessage.type === 'TYPE_INBOUND'));
const lastMessageAge = lastMessage ?
  Math.round((now - new Date(lastMessage.dateAdded || lastMessage.createdAt).getTime()) / (1000 * 60 * 60)) : null;

// === BUILD SYSTEM PROMPT ===
const connectSection = hasConnectTag
  ? 'This contact already has a "connect" tag — they have had their free intro chat. Skip offering a connect call. Focus on qualification and program recommendation.'
  : 'This contact does NOT have a "connect" tag. Your primary goal is to book a free 15-minute chat. Position it naturally: "I would love to hop on a quick chat to learn more about where you are at and what you are working toward." Never call it a "connect call" — just frame it as a casual conversation.';

let webinarSection = 'No upcoming webinars within 3 weeks.';
if (webinarStatus.length > 0) {
  webinarSection = webinarStatus.map(w =>
    w.isRegistered
      ? 'Webinar "' + w.name + '" (' + w.date + '): Contact IS registered. Ask if they are planning to attend. You CAN offer a pre-workshop connect chat even if they have the connect tag — this is an exception.'
      : 'Webinar "' + w.name + '" (' + w.date + '): Contact is NOT registered. Invite them!'
  ).join('\n   ');
}

let pastWebinarSection = '';
if (pastWebinars.length > 0) {
  pastWebinarSection = pastWebinars.map(w =>
    w.hasAttended
      ? 'Past webinar "' + w.name + '": Contact ATTENDED' + (w.daysAttended.length > 0 ? ' (days: ' + w.daysAttended.join(', ') + ')' : '') + '. Ask what they thought about it! If they do not have a connect tag, offer a connect chat.'
      : w.isRegistered
        ? 'Past webinar "' + w.name + '": Contact was REGISTERED but did NOT attend. Gently mention it.'
        : ''
  ).filter(Boolean).join('\n   ');
}

const systemPrompt = $input.first().json.Context;

const userPrompt = 'Contact: ' + ctx.firstName + (ctx.lastName ? ' ' + ctx.lastName : '') + '\nTags: ' + ((ctx.tags || []).join(', ') || 'none') + '\nLast message from: ' + (lastMessageIsInbound ? 'contact (their turn — we should respond)' : 'Shimrit (our turn — this is a follow-up)') + '\nLast message age: ' + (lastMessageAge !== null ? lastMessageAge + ' hours ago' : 'unknown') + '\nCan send free-form: ' + (canSendFreeForm ? 'YES (within 24h window)' : 'NO (outside 24h — will need template)') + '\n\nConversation history (oldest to newest):\n' + (history || '[No previous messages — this would be the first outreach]');

// Build OpenAI request body as plain object
const requestBody = {
  model: 'gpt-4o-mini',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ],
  max_tokens: 300,
  temperature: 0.7
};

return [{
  json: {
    contactId: ctx.contactId,
    conversationId: ctx.conversationId,
    firstName: ctx.firstName,
    lastName: ctx.lastName,
    tags: ctx.tags,
    canSendFreeForm,
    lastMessageIsInbound,
    lastMessageAge,
    requestBody
  }
}];

const ctx = $('Build AI Prompt').first().json;
const response = $input.first().json;

// Handle OpenAI errors
if (response.error) {
  return [{
    json: {
      contactId: ctx.contactId,
      firstName: ctx.firstName,
      error: 'OpenAI API error: ' + JSON.stringify(response.error),
      canSendFreeForm: false
    }
  }];
}

const aiMessage = response.choices[0].message.content.trim();

// Prepare the GHL send body
const sendBody = {
  type: 'WhatsApp',
  contactId: ctx.contactId,
  message: aiMessage
};

return [{
  json: {
    contactId: ctx.contactId,
    conversationId: ctx.conversationId,
    firstName: ctx.firstName,
    lastName: ctx.lastName,
    tags: ctx.tags,
    canSendFreeForm: ctx.canSendFreeForm,
    lastMessageIsInbound: ctx.lastMessageIsInbound,
    aiMessage,
    sendBody
  }
}];

const row = $input.first().json;

// Build the GHL send body
const sendBody = {
  type: 'WhatsApp',
  contactId: row['Contact ID'],
  message: row['AI Message']
};

return [{
  json: {
    sendBody,
    contactId: row['Contact ID'],
    contactName: row['Contact Name'],
    conversationId: row['Conversation ID'],
    aiMessage: row['AI Message'],
    rowNumber: row.row_number
  }
}];
